{"path":"workflow.py","content":""""Order reconciliation - v1 contract (spec-v1.md).

Pure functions only. No file/network/process access.
Allowed imports: csv, io, json, decimal, hashlib, collections, datetime, math.
"""

import csv
import io
from decimal import Decimal, InvalidOperation

_ALLOWED_POLICY_V1 = "v1"


def _parse_amount_to_cents(raw, context):
    """Parse a non-negative decimal string with at most 2 decimals to integer cents.

    Uses Decimal fixed-point; never float multiplication.
    Raises ValueError on empty/NaN/Infinity/negative/>2 decimals.
    """
    if raw is None:
        raise ValueError("%s: missing amount" % context)
    text = raw.strip()
    if text == "":
        raise ValueError("%s: empty amount" % context)
    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError("%s: invalid amount %r" % (context, raw))
    if not value.is_finite():
        raise ValueError("%s: non-finite amount %r" % (context, raw))
    if value < 0:
        raise ValueError("%s: negative amount %r" % (context, raw))
    # At most two decimal places (v1).
    sign, digits, exponent = value.as_tuple()
    if exponent < -2:
        raise ValueError("%s: more than two decimals %r" % (context, raw))
    cents = value.scaleb(2).to_integral_value()
    if cents != value.scaleb(2):
        raise ValueError("%s: rounding needed %r" % (context, raw))
    return int(cents)


def _read_rows(csv_text, required_header, kind):
    """Parse CSV text into (header, list_of_dicts). Raises ValueError on shape issues."""
    if csv_text is None:
        raise ValueError("%s csv is None" % kind)
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row and any(field.strip() != "" for field in row)]
    if not rows:
        raise ValueError("%s csv: missing header" % kind)
    header = [field.strip() for field in rows[0]]
    if header != required_header:
        raise ValueError(
            "%s csv: bad header %r, expected %r" % (kind, header, required_header)
        )
    records = []
    for lineno, row in enumerate(rows[1:], start=2):
        if len(row) != len(header):
            raise ValueError("%s csv line %d: wrong column count" % (kind, lineno))
        records.append({header[i]: row[i].strip() for i in range(len(header))})
    return header, records


def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    """Reconcile paid orders against refunds per the v1 contract.

    Returns:
        {
          "orders": [{"order_id", "customer", "paid_cents", "refund_cents", "net_cents"}...],
          "customers": [{"customer", "net_cents"}...],
          "totals": {"paid_cents", "refund_cents", "net_cents"}
        }
    Raises ValueError on any contract violation.
    """
    if policy != _ALLOWED_POLICY_V1:
        raise ValueError("unsupported policy %r" % (policy,))
    # cutoff is reserved for future policies; v1 ignores it but validates type-freely.
    if cutoff is not None:
        raise ValueError("cutoff is not supported by policy v1")

    # ---- Orders ----
    _, order_rows = _read_rows(
        orders_csv, ["order_id", "customer", "amount", "status", "created_at"], "orders"
    )
    orders = {}  # order_id -> dict(customer, status, paid_cents, raw tuple)
    for rec in order_rows:
        oid = rec["order_id"]
        if oid == "":
            raise ValueError("orders: empty order_id")
        status = rec["status"]
        if status not in ("paid", "cancelled"):
            raise ValueError("orders: unknown status %r for %s" % (status, oid))
        paid_cents = _parse_amount_to_cents(rec["amount"], "orders %s" % oid)
        key = (oid, rec["customer"], rec["amount"], status, rec["created_at"])
        if oid in orders:
            if orders[oid]["_key"] == key:
                continue  # exact duplicate row: counted once
            raise ValueError("orders: duplicate order_id %s with different fields" % oid)
        orders[oid] = {
            "customer": rec["customer"],
            "status": status,
            "paid_cents": paid_cents,
            "_key": key,
        }

    # ---- Refunds ----
    _, refund_rows = _read_rows(
        refunds_csv, ["refund_id", "order_id", "amount"], "refunds"
    )
    refunds = {}  # refund_id -> dict(order_id, amount_cents, raw tuple)
    for rec in refund_rows:
        rid = rec["refund_id"]
        if rid == "":
            raise ValueError("refunds: empty refund_id")
        amount_cents = _parse_amount_to_cents(rec["amount"], "refunds %s" % rid)
        key = (rid, rec["order_id"], rec["amount"])
        if rid in refunds:
            if refunds[rid]["_key"] == key:
                continue  # exact duplicate row: counted once
            raise ValueError("refunds: duplicate refund_id %s with different fields" % rid)
        refunds[rid] = {
            "order_id": rec["order_id"],
            "amount_cents": amount_cents,
            "_key": key,
        }

    # ---- Validate refunds against orders ----
    refund_by_order = {}
    for rid in sorted(refunds):
        refund = refunds[rid]
        oid = refund["order_id"]
        order = orders.get(oid)
        if order is None:
            raise ValueError("refunds: %s references unknown order %s" % (rid, oid))
        if order["status"] != "paid":
            raise ValueError("refunds: %s references cancelled order %s" % (rid, oid))
        refund_by_order[oid] = refund_by_order.get(oid, 0) + refund["amount_cents"]

    for oid in sorted(refund_by_order):
        order = orders[oid]
        if order["status"] == "paid" and refund_by_order[oid] > order["paid_cents"]:
            raise ValueError(
                "refunds: order %s refunded %d cents exceeds paid %d cents"
                % (oid, refund_by_order[oid], order["paid_cents"])
            )

    # ---- Build result (paid orders only) ----
    result_orders = []
    customer_net = {}
    total_paid = total_refund = 0
    for oid in sorted(orders):
        order = orders[oid]
        if order["status"] != "paid":
            continue
        paid = order["paid_cents"]
        refunded = refund_by_order.get(oid, 0)
        net = paid - refunded
        result_orders.append(
            {
                "order_id": oid,
                "customer": order["customer"],
                "paid_cents": paid,
                "refund_cents": refunded,
                "net_cents": net,
            }
        )
        customer = order["customer"]
        customer_net[customer] = customer_net.get(customer, 0) + net
        total_paid += paid
        total_refund += refunded

    result_customers = [
        {"customer": name, "net_cents": customer_net[name]}
        for name in sorted(customer_net)
    ]
    return {
        "orders": result_orders,
        "customers": result_customers,
        "totals": {
            "paid_cents": total_paid,
            "refund_cents": total_refund,
            "net_cents": total_paid - total_refund,
        },
    }


def export_bundle(result):
    """Serialize a reconcile result into a small bundle of JSON files."""
    import json

    return {"summary.json": json.dumps(result, sort_keys=True)}
"}
